    users = store.get_all()
    if domain is None:
        return len(users)

    count = 0
    domain = domain.lower()
    for user in users:
        email = user["email"]
        if "@" in email:
            user_domain = email.split("@")[-1].lower()
            if user_domain == domain:
                count += 1
    return count
